text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لشركة الأفق الرقمي للخدمات التقنية",
  "planted": [
    {
      "slot": "p1",
      "text": "في حال وقوع أي حادث أمني أو وصول غير مصرح به للبيانات، تقوم الجهة المعنية بالتعامل مع الأمر داخلياً وفقاً لتقديرها التشغيلي المحض، مع إمكانية إخطار الأطراف المتضررة خلال زمني مدمج يناسب طبيعة العمليات ودون الالتزام بأطر زمنية ضيقة."
    },
    {
      "slot": "p2",
      "text": "تحتفظ الشركة بسجلات البيانات والملفات الرقمية للمستخدمين لفترات زمنية ممتدة وغير محدودة بغرض استمرارية تحسين جودة الخدمة والأرشفة التاريخية، ودون وجود التزام زمني محدد لإتلافها أو محوها نهائياً."
    },
    {
      "slot": "p3",
      "text": "يُعتبر مجرد تصفح المنصة أو الاستمرار في استخدام الخدمات بمثابة موافقة ضمنية ونهائية على كافة سياسات المعالجة الحالية والمستقبلية، ولا يُتاح للمستخدم التراجع عن هذه الموافقة أو تقييدها طالما كان الحساب نشطاً."
    },
    {
      "slot": "p4",
      "text": "نقتصر في معالجة البيانات الشخصية حصرياً على الغرض الرئيسي الذي جُمعت من أجله والمتمثل في تقديم الخدمات التشغيلية وتحسين تجربة المستخدم عبر المنصة."
    },
    {
      "slot": "p5",
      "text": "يحق للمستخدمين التواصل مع فريق الدعم الفني للاستفسار عن طبيعة المعلومات المسجلة وطلب مراجعتها أو تعديلها وفقاً لما تقره العمليات الإدارية المعتمدة لدى الشركة."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية وأجور الاشتراك لجدول الأسعار المعلن عبر الموقع، وتتم عمليات الدفع حصرياً عبر قنوات الدفع الإلكترونية المعتمدة.",
    "تبدأ هذه الاتفاقية فاعليتها فور تسجيل الحساب وتستمر حتى قيام إحدى الطرفين بإنهاء التعاقد وفقاً للإجراءات التنظيمية المتبعة.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر التبعية الناتجة عن انقطاع الخدمة أو الأعطال التقنية الخارجة عن الإرادة.",
    "تُفسر هذه الشروط وتخضع للأنظمة المعمول بها في المملكة العربية السعودية، وتختص المحاكم المختصة بالفصل في أي النزاع ينشأ عنها.",
    "تعتبر حقوق الملكية الفكرية للتصميمات والبرمجيات والعلامات التجارية ملكاً خالصاً للشركة ولا يجوز استخدامها أو استنساخها دون إذن خطي مسبق.",
    "تتم الإشعارات الرسمية والمراسلات المتبادلة بين الطرفين عبر البريد الإلكتروني المسجل في الحساب أو من خلال الإشعارات الداخلية ضمن منصة الخدمة."
  ]
}
